// Input data
const inputData = $input.all()[0].json.response || [];

// Workday settings
const WORKDAY_START = "09:00:00";
const WORKDAY_END = "18:00:00";
const SLOT_DURATION = 30 * 60 * 1000; // 30 minutes

// Parse date safely
const parseDate = (datetime) => {
  const parsedDate = new Date(datetime);
  return isNaN(parsedDate.getTime()) ? null : parsedDate;
};

// Generate 30-minute start times
const generateStartTimes = (start, end) => {
  const startTimes = [];
  let current = new Date(start);

  while (current < end) {
    startTimes.push(
      current.toLocaleTimeString("en-US", {
        timeZone: "Asia/Manila",
        hour: "2-digit",
        minute: "2-digit",
        hour12: true,
      })
    );

    current = new Date(current.getTime() + SLOT_DURATION);
  }

  return startTimes;
};

// Find consecutive available ranges
const findWideOpenRanges = (startTimes) => {
  if (startTimes.length < 3) return [];

  const ranges = [];
  let rangeStart = null;
  let consecutiveCount = 0;

  for (let i = 0; i < startTimes.length - 1; i++) {
    const currentTime = Date.parse(
      `2000-01-01 ${startTimes[i]}`
    );

    const nextTime = Date.parse(
      `2000-01-01 ${startTimes[i + 1]}`
    );

    const diff = nextTime - currentTime;

    if (diff === SLOT_DURATION) {
      consecutiveCount++;

      if (rangeStart === null) {
        rangeStart = startTimes[i];
      }
    } else {
      if (consecutiveCount >= 2) {
        ranges.push(
          `${rangeStart} to ${startTimes[i]}`
        );
      }

      rangeStart = null;
      consecutiveCount = 0;
    }
  }

  if (consecutiveCount >= 2) {
    ranges.push(
      `${rangeStart} to ${
        startTimes[startTimes.length - 1]
      }`
    );
  }

  return ranges;
};

// Group meetings by date
const meetingsByDate = inputData.reduce((acc, meeting) => {
  const start = parseDate(meeting.start);
  const end = parseDate(meeting.end);

  if (!start || !end) {
    return acc;
  }

  const dateKey = start.toISOString().split("T")[0];

  if (!acc[dateKey]) {
    acc[dateKey] = [];
  }

  acc[dateKey].push({
    start,
    end,
  });

  return acc;
}, {});

// Generate availability
const availability = Object.keys(meetingsByDate)
  .filter((date) => {
    const dayOfWeek = new Date(date).getUTCDay();

    // Exclude Sunday (0) and Saturday (6)
    return dayOfWeek !== 0 && dayOfWeek !== 6;
  })
  .map((date) => {

    const workdayStart = new Date(
      `${date}T09:00:00+08:00`
    );

    const workdayEnd = new Date(
      `${date}T18:00:00+08:00`
    );

    const dayMeetings = meetingsByDate[date]
      .sort((a, b) => a.start - b.start);

    let availableStartTimes = [];
    let lastEnd = workdayStart;

    for (const meeting of dayMeetings) {

      if (meeting.start > lastEnd) {
        availableStartTimes = availableStartTimes.concat(
          generateStartTimes(
            lastEnd,
            meeting.start
          )
        );
      }

      if (meeting.end > lastEnd) {
        lastEnd = meeting.end;
      }
    }

    if (lastEnd < workdayEnd) {
      availableStartTimes = availableStartTimes.concat(
        generateStartTimes(
          lastEnd,
          workdayEnd
        )
      );
    }

    return {
      date: new Date(
        `${date}T00:00:00+08:00`
      ).toLocaleDateString("en-US", {
        timeZone: "Asia/Manila",
        weekday: "long",
        year: "numeric",
        month: "long",
        day: "numeric",
      }),

      availableStartTimes,
      wideOpenRanges: findWideOpenRanges(
        availableStartTimes
      ),
    };
  });

// Format output text
const availableTimes = availability
  .map(
    ({
      date,
      availableStartTimes,
      wideOpenRanges,
    }) => {

      const times =
        availableStartTimes.length > 0
          ? availableStartTimes
              .map((time) => `- ${time}`)
              .join("\n")
          : "No available slots";

      const ranges =
        wideOpenRanges.length > 0
          ? `Wide Open Ranges:\n${wideOpenRanges
              .map((range) => `- ${range}`)
              .join("\n")}`
          : "Wide Open Ranges: None";

      return `### ${date}

Available Start Times:
${times}

${ranges}`;
    }
  )
  .join("\n\n");

// Final Output
return {
  json: {
    availableTimes,
    availability,
  },
};

const results = [];

for (const item of $input.all()) {
  const toolCalls = item.json.body.message.toolCalls;

  const extractedArgs = toolCalls[0].function.arguments;

  results.push({
    json: {
      ...item.json,
      safe_arguments: extractedArgs
    }
  });
}

return results;

